          foundGap = true;
          for (var _i = 0; _i < existingPositions.length; _i++) {
            var _existingPos = existingPositions[_i];
            var _distance = Math.sqrt(Math.pow(x - _existingPos.x, 2) + Math.pow(y - _existingPos.y, 2));
            if (_distance < minSpacing) {
              foundGap = false;
              break;
            }
          }
