      cc.log("[BattleController] \u7ECF\u9A8C\u5956\u52B1: " + expReward + " \u70B9/\u4EBA\uFF08\u5305\u62EC\u6B7B\u4EA1\u7684\u5355\u4F4D\uFF09");
