    cc.log("[BattleRecorder] \u505C\u6B62\u8BB0\u5F55\uFF0C\u5171\u8BB0\u5F55 " + this.battleRecord.events.length + " \u4E2A\u4E8B\u4EF6\uFF0C\u8017\u65F6 " + this.battleRecord.duration + "ms");
